import java.util.Scanner;

public class Main {
    static final long MOD_CONST = 1000000007;

    static long fast_power(long base, long exp) {
        long res = 1;
        for (int i = 0; i < exp; ++i) {
            res = (res * base) % MOD_CONST;
        }
        return res;
    }

    static long calculate(long p, long k) {
        if (k <= 1) {
            return fast_power(p, p - 1 + k);
        }
        int cycle_length = 1;
        long val = k;
        while (val != 1) {
            val = (val * k) % p;
            cycle_length++;
        }
        return fast_power(p, (p - 1) / cycle_length);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long p = scanner.nextLong();
        long k = scanner.nextLong();
        System.out.println(calculate(p, k));
        scanner.close();
    }
}
